const D=window.Duties;D.prepare(state);if(state.demoDutiesVersion!==1)change(s=>window.DutyDemo.seed(s));
const dutiesRouteBase=route,dutiesShellBase=adminShell,dutiesMyBase=myPage;
adminShell=function(section,body){const box=document.createElement('div');box.innerHTML=dutiesShellBase(section,body);const nav=box.querySelector('nav');if(nav){let a=nav.querySelector('a[href="#/admin/contacts"]');if(!a){a=document.createElement('a');a.href='#/admin/contacts';nav.append(a);}a.textContent='担当・役割管理';a.classList.toggle('active',section==='contacts');}return box.innerHTML;};
function ownDutyPanel(){const items=D.own(state,current().id);if(!items.length)return '';return '<section class="panel" id="my-duties"><div class="eyebrow">YOUR TEAM ROLE</div><h2>あなたの担当</h2><div class="grid-2">'+items.map(x=>'<article class="panel"><h3>'+esc(x.label)+'</h3>'+pill(D.STATUS[x.status])+'<p>'+esc(x.scope)+'</p><p>'+esc(x.description)+'</p>'+(x.dueDate?'<p>対応予定日：'+esc(x.dueDate)+'</p>':'')+'</article>').join('')+'</div>'+(organizer()?'<a href="#/admin/contacts?mine=yes" class="btn btn-outline">自分の担当を一覧で確認</a>':'')+'</section>';}
myPage=function(){const html=dutiesMyBase();if(!current())return html;const box=document.createElement('div');box.innerHTML=html;const panel=ownDutyPanel();const guide=box.querySelector('.registration-guide');if(guide)guide.insertAdjacentHTML('afterend',panel);else box.insertAdjacentHTML('beforeend',frame(panel));return box.innerHTML;};
function dutyParams(){return new URLSearchParams(location.hash.split('?')[1]||'');}
function dutyForm(x={}){return '<section class="panel" id="duty-editor"><h2>'+(x.id?'担当を編集する':'担当を登録する')+'</h2><p>1人に複数の担当を登録できます。外部協力者にログイン権限は付与されません。</p><form data-duty-form="save">'+(x.id?'<input type="hidden" name="id" value="'+x.id+'"><input type="hidden" name="revision" value="'+x.revision+'">':'')+'<div class="grid-2">'+select('roleKey','役割',[['','役割を選択'],...Object.entries(D.ROLES)],x.roleKey||'')+field('customRole','その他の役割名',x.customRole||'','text',false)+select('kind','担当者の区分',[['member','登録者から選ぶ'],['external','外部協力者']],x.kind||'member')+select('userId','登録者（外部協力者の場合は不要）',[['','登録者を選択'],...state.people.map(p=>[p.id,p.number+' '+p.name+' ／ '+R.classLabel(p.class)])],x.userId||'')+field('externalName','外部協力者の氏名',x.externalName||'','text',false)+field('contact','外部協力者の連絡メモ（幹事のみ）',x.contact||'','text',false)+select('class','対象クラス',[['0','全体・クラス指定なし'],...Array.from({length:10},(_,i)=>[i+1,'3年'+(i+1)+'組'])],x.class||0)+select('status','担当状況',Object.entries(D.STATUS),x.status||'active')+field('scope','担当範囲・係名',x.scope||'','text',false)+field('dueDate','対応予定日（任意）',x.dueDate||'','date',false)+'</div><label class="field">担当内容（本人にも表示）<textarea name="description" maxlength="2000" rows="3">'+esc(x.description||'')+'</textarea></label><label class="field">幹事内メモ（本人向け画面には非表示）<textarea name="note" maxlength="2000" rows="3">'+esc(x.note||'')+'</textarea></label>'+field('reason','設定・変更理由')+'<p class="mini-note">解除する場合は担当状況を「担当解除」にして保存します。記録と変更履歴は残ります。</p><p class="error-text" role="alert"></p><button class="btn">担当を保存する</button> <a class="btn btn-outline" href="#/admin/contacts">一覧へ戻る</a></form></section>';}
function dutyPage(){const f=Object.fromEntries(dutyParams()),editing=Number(f.edit||0),items=D.filter(D.rows(state,current().id),f,current().id);if(f.mode==='classes'&&owner()){const html=classContactsAdmin(Number(f.class||1));return html.replace('<h2>クラス幹事を設定する</h2>','<p><a href="#/admin/contacts">← 担当一覧へ</a></p><h2>クラス幹事を設定する</h2>');}const stats='<div class="stats-grid">'+[['担当数',D.rows(state,current().id).length+'件'],['自分の担当数',D.own(state,current().id).length+'件'],['外部協力件数',state.duties.filter(x=>x.kind==='external'&&x.status!=='inactive').length+'件']].map(x=>'<div class="stat"><small>'+x[0]+'</small><strong>'+x[1]+'</strong></div>').join('')+'</div>';
const filters='<section class="panel"><h2>担当を探す</h2><div class="button-row"><a class="btn btn-outline" href="#/admin/contacts?view=results" data-duty-results>すべて</a><a class="btn btn-outline" href="#/admin/contacts?mine=yes&view=results" data-duty-results>自分の担当</a><a class="btn btn-outline" href="#/admin/contacts?kind=external&view=results" data-duty-results>外部協力者</a><a class="btn btn-outline" href="#/admin/contacts?role=class&view=results" data-duty-results>クラス幹事</a></div><form data-duty-form="filter"><div class="grid-2">'+field('q','氏名・担当内容で検索',f.q||'','search',false)+select('role','担当',[['','すべて'],['class','クラス幹事'],...Object.entries(D.ROLES)],f.role||'')+select('class','クラス（対象または所属）',[['','すべて'],...Array.from({length:10},(_,i)=>[i+1,'3年'+(i+1)+'組'])],f.class||'')+select('kind','区分',[['','すべて'],['member','登録者'],['external','外部協力者']],f.kind||'')+select('status','担当状況',[['','すべて'],...Object.entries(D.STATUS)],f.status||'')+select('mine','表示対象',[['','全担当'],['yes','自分の担当']],f.mine||'')+'</div><button class="btn">絞り込む</button></form></section>';
let body='<h1>担当・役割管理</h1><p class="mini-note">表示中の担当割当は架空の見本です。実際の幹事体制ではありません。</p><p>同窓会を支える担当をまとめて確認できます。担当名とシステムの管理権限は別です。</p>'+stats+filters+'<div class="button-row">'+(owner()?'<a class="btn" href="#/admin/contacts?new=yes">担当を追加</a><a class="btn btn-outline" href="#/admin/contacts?mode=classes">クラス幹事の設定</a>':'<p>設定・編集は管理者が行います。</p>')+'<button class="btn btn-outline" data-duty-csv>表示中の一覧CSV</button></div><p id="duty-results" tabindex="-1">'+items.length+'件を表示 ／ 氏名を押すと担当の詳細を確認できます。</p>'+table(['役割・状況','担当者','対象・担当内容','予定日','操作'],items.map(x=>[esc(x.label)+'<br>'+pill(D.STATUS[x.status]),'<a href="#/admin/contacts?'+(x.source==='class'?'person='+x.userId:'detail='+x.id)+'">'+esc(x.name)+'</a><br>'+esc(x.kind==='external'?'外部協力者':R.classLabel(x.personClass)),esc(x.class?'3年'+x.class+'組':'全体')+'<br>'+esc(x.scope)+'<br>'+esc(x.description),esc(x.dueDate||'—'),owner()?'<a class="btn btn-outline" href="#/admin/contacts?'+(x.source==='class'?'mode=classes&class='+x.class:'edit='+x.id)+'">編集</a>':'閲覧のみ']));
const detail=Number(f.detail||0),person=Number(f.person||0);if(detail||person){const selected=D.rows(state,current().id).filter(x=>person?x.userId===person:x.source==='duty'&&x.id===detail);body+='<section class="panel"><h2>担当の詳細</h2>'+selected.map(x=>'<article><h3>'+esc(x.name)+' ／ '+esc(x.label)+'</h3><p>'+esc(x.description)+'</p><p>担当範囲：'+esc(x.scope||'—')+' ／ '+D.STATUS[x.status]+'</p>'+(x.source==='duty'?'<p>連絡メモ：'+esc(x.contact||'—')+'</p><p>幹事内メモ：'+esc(x.note||'—')+'</p><p>更新日時：'+esc(x.updated)+'</p>':'')+'</article>').join('')+'</section>';}
if(owner()&&(editing||f.new)){const x=editing?state.duties.find(x=>x.id===editing):{};body+=x?dutyForm(x):'<p class="error-text">担当記録がありません。</p>';}
return adminShell('contacts',body);}
route=function(){const path=location.hash.slice(1).split('?')[0];if(/^\/admin\/contacts(?:\/|$)/.test(path)&&organizer()){const oldClass=Number(path.split('/')[3]);if(oldClass){location.hash='/admin/contacts?mode=classes&class='+oldClass;return;}renderSessionBar();main.innerHTML=dutyPage();if(dutyParams().get('view')==='results'){const results=document.querySelector('#duty-results');results?.focus({preventScroll:true});results?.scrollIntoView({block:'start',behavior:'instant'});}else window.scrollTo(0,0);if(dutyParams().has('new')||dutyParams().has('edit')||dutyParams().has('detail')||dutyParams().has('person'))document.querySelector('#duty-editor, main article:last-of-type')?.scrollIntoView({block:'center'});return;}dutiesRouteBase();};window.removeEventListener('hashchange',dutiesRouteBase);window.addEventListener('hashchange',route);
document.addEventListener('submit',ev=>{const f=ev.target;if(!f.dataset.dutyForm)return;ev.preventDefault();ev.stopImmediatePropagation();const d=Object.fromEntries(new FormData(f));if(f.dataset.dutyForm==='filter'){const params=new URLSearchParams(Object.entries(d).filter(x=>x[1]));params.set('view','results');const next='#/admin/contacts?'+params.toString();if(location.hash===next)route();else location.hash=next;return;}try{change(s=>D.save(s,d,current()?.id));location.hash='/admin/contacts';route();toast('担当と変更履歴を保存しました');}catch(e){f.querySelector('.error-text').textContent=e.message;}},true);
document.addEventListener('click',ev=>{if(!ev.target.closest('[data-duty-csv]'))return;try{const items=D.filter(D.rows(state,current()?.id),Object.fromEntries(dutyParams()),current().id);const rows=items.map(x=>({'役割':x.label,'担当者':x.name,'区分':x.kind==='external'?'外部協力者':'登録者','対象クラス':x.class?'3年'+x.class+'組':'全体','担当範囲':x.scope,'担当内容':x.description,'状況':D.STATUS[x.status],'対応予定日':x.dueDate||''}));download('担当一覧.csv',R.toCSV([['役割','担当者','区分','対象クラス','担当範囲','担当内容','状況','対応予定日'],...rows.map(x=>Object.values(x))]));}catch(e){toast(e.message);}},true);
route();

document.addEventListener('click',ev=>{const a=ev.target.closest('a[data-duty-results]');if(!a||ev.button!==0||ev.metaKey||ev.ctrlKey||ev.shiftKey||ev.altKey)return;ev.preventDefault();if(location.hash===a.hash)route();else location.hash=a.hash;});
